<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { getEvents, getTask, usingMockProcurementService } from '../../services/procurement-review'; import type { ReviewTask } from '../../types/procurement-review'
const route=useRoute(); const router=useRouter(); const task=ref<ReviewTask>(); const error=ref(''); let timer: number | undefined; let lastEventId: string | undefined
async function load(){ try { const projectId=String(route.params.projectId); const taskId=String(route.params.taskId); const serverTask=await getTask(projectId, taskId); if(!serverTask)return; if(usingMockProcurementService && task.value?.status==='parsing'){ serverTask.progress=Math.min(100,task.value.progress+20); if(serverTask.progress>=100)serverTask.status='reviewing' } task.value=serverTask; if(!usingMockProcurementService){const events=await getEvents(projectId,taskId,lastEventId); lastEventId=events.at(-1)?.id??lastEventId} } catch { error.value='进度读取失败，请稍后重试。' } }
onMounted(async()=>{await load(); timer=window.setInterval(load,2000)}); onUnmounted(()=>clearInterval(timer))
</script>
<template><section class="page-head"><p class="crumb">审查任务 / 解析与 AI 审查进度</p><h1>正在准备候选问题与证据</h1><p>解析质量、进度和失败原因均由后端任务状态决定；页面每 2 秒读取一次进度。</p></section><section class="page-body"><div v-if="!task" class="state-card error-state">资源不存在或尚未加载。</div><div v-else class="progress-card"><span class="status-chip">{{ task.status === 'failed' ? '处理失败' : '处理中' }}</span><h2>{{ task.title }}</h2><p>{{ task.document?.file_name }}</p><div class="progress-track"><i :style="{ width: `${task.progress}%` }" /></div><strong>{{ task.progress }}%</strong><ol class="timeline"><li :class="{ done: task.progress >= 20 }">文件安全校验与登记</li><li :class="{ done: task.progress >= 45 }">文档解析与质量检查</li><li :class="{ done: task.progress >= 80 }">AI 审查与证据校验</li><li :class="{ done: task.progress >= 100 }">等待人工确认</li></ol><button v-if="task.progress >= 100 || task.status === 'operator_review'" class="button primary" @click="router.push({ name:'procurement-workbench', params:{projectId: task.project_id, taskId:task.id} })">进入审核工作台</button></div></section></template>
